// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address callerCandidate, string memory description) internal {
        vm.assume(callerCandidate == address(this) || callerCandidate != address(this));
        vm.assume((callerCandidate == address(this)) == c.isAdmin(address(this)));
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assertTrue((callerCandidate == address(this)) == (!reverted));
    }

    function testFuzz_run(address callerCandidate, string memory description) public {
        vm.assume(callerCandidate.code.length == 0 && uint160(callerCandidate) > 0xffff && callerCandidate != address(this) && callerCandidate != address(c) && callerCandidate != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && callerCandidate != 0x000000000000000000636F6e736F6c652e6c6f67 && callerCandidate != 0x4e59b44847b379578588920cA78FbF26c0B4956C && callerCandidate != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callerCandidate, description);
    }

    receive() external payable { }
}
